def wc(t): return len(re.findall(r"\b[\w'’-]+\b",t))
rows=[];emails=[]
for (n,reg,name,slug,meth,to,piece,kind,angle,img,lim,fn,skip) in R:
    if skip:
        rows.append((reg,n,name,'SKIP',piece,'-','-','-','-','skipped: '+skip));continue
    head,body=fn()
    if 'op-ed' in kind or kind.startswith('article'):
        body=body+"\n\n---\n"+BIO+"\n"+DISC3
    w=wc(body)
    imgp=img
    first=img.split(' ')[0]
    if os.path.exists(IMG+first): imgp=IMG+first+(' '+' '.join(img.split(' ')[1:]) if ' ' in img else '')
    status='ready'
    notes=[]
    if 'BLOCKER' in img or 'BLOCKER' in to: status='ready (blocked: see note)'
    if meth=='account': status='ready (account needed)'
    kindl=kind.lower()
    if 'pitch' in kindl or kind=='letter': subj=head
    elif 'op-ed' in kindl or kindl.startswith('article'): subj=('Op-ed submission (exclusive): ' if 'op-ed' in kindl else 'Article submission (exclusive): ')+head
    else: subj=head
    if slug=='maryland-matters': subj='commentary: '+head
    md=f"""# {name} ({reg} #{n})

| Field | Value |
|---|---|
| Method | {meth} |
| To / URL | {to} |
| Piece | {piece} |
| Type | {kind} |
| Angle | {angle} |
| Image | {imgp} |
| Limit | {lim} |
| Word count (body) | {w} |
| Status | {status} - NOT SENT |

**Subject / headline:** {subj}

---

{('# '+head+chr(10)+chr(10)) if not ('pitch' in kindl or kind=='letter' or 'expert' in kindl) else ''}{body}
"""
    open(f"{OUT}/drafts/{slug}.md",'w').write(md)
    rows.append((reg,n,name,meth,piece,kind,angle,imgp.replace(OUT+'/',''),w,status))
    if meth=='email':
        att=imgp if os.path.exists(IMG+first) and 'no attach' not in to else 'none'
        emails.append((reg,n,name,to,subj,body,att,slug,kind))
import json;json.dump({'rows':rows,'emails':[e[:5]+e[6:] for e in emails]},open(OUT+'/src/_rows.json','w'),indent=1)
